package com.pvpwhgame.hyperoscharge.service

import android.app.*
import android.content.Intent
import android.os.IBinder
import com.pvpwhgame.hyperoscharge.MainActivity
import com.pvpwhgame.hyperoscharge.data.*
import com.pvpwhgame.hyperoscharge.ui.ModuleHtmlParser
import kotlinx.coroutines.*
import kotlinx.coroutines.flow.MutableStateFlow

class ChargeMonitorService : Service() {

    companion object {
        val statusFlow = MutableStateFlow(ChargeStatus())
        val historyFlow = MutableStateFlow<List<HistoryPoint>>(emptyList())
        val learnDataFlow = MutableStateFlow<Map<String, LearnData>>(emptyMap())
        val modeDescsFlow = MutableStateFlow<Map<String, String>>(emptyMap())
        private const val NOTIFICATION_ID = 1001
        private const val CHANNEL_ID = "charge_monitor"
    }

    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)

    override fun onCreate() {
        super.onCreate()
        createNotificationChannel()
        startForeground(NOTIFICATION_ID, buildNotification("初始化中..."))
        startMonitoring()
    }

    override fun onBind(intent: Intent?): IBinder? = null

    override fun onDestroy() {
        scope.cancel()
        super.onDestroy()
    }

    private fun startMonitoring() {
        // 每 2 秒读取实时状态
        scope.launch {
            while (isActive) {
                try {
                    val json = ShellExecutor.readFile(ModuleConfig.STATUS_JSON)
                    if (json != null) {
                        val status = ChargeStatus.parse(json)
                        statusFlow.value = status
                        updateNotification(status)
                    }
                } catch (_: Exception) {}
                delay(2000)
            }
        }
        // 每 5 秒读取历史数据
        scope.launch {
            while (isActive) {
                try {
                    val csv = ShellExecutor.readFile(ModuleConfig.HISTORY_CSV)
                    if (csv != null) {
                        historyFlow.value = HistoryPoint.parseCsv(csv)
                    }
                } catch (_: Exception) {}
                delay(5000)
            }
        }
        // 每 10 秒读取所有模式的学习数据 + 从 HTML 解析模式描述
        scope.launch {
            while (isActive) {
                try {
                    val descs = ModuleHtmlParser.getModeDescriptions()
                    modeDescsFlow.value = descs

                    val allLearn = mutableMapOf<String, LearnData>()
                    for (mode in ChargeMode.entries) {
                        val content = ShellExecutor.readFile(mode.learnFile)
                        allLearn[mode.key] = if (content != null) LearnData.parse(content) else LearnData()
                    }
                    learnDataFlow.value = allLearn
                } catch (_: Exception) {}
                delay(10000)
            }
        }
    }

    private fun createNotificationChannel() {
        val channel = NotificationChannel(
            CHANNEL_ID, "充电监控",
            NotificationManager.IMPORTANCE_LOW
        ).apply {
            description = "充电优化实时状态"
            setShowBadge(false)
        }
        (getSystemService(NOTIFICATION_SERVICE) as NotificationManager)
            .createNotificationChannel(channel)
    }

    private fun buildNotification(text: String): Notification {
        val pending = PendingIntent.getActivity(
            this, 0,
            Intent(this, MainActivity::class.java),
            PendingIntent.FLAG_IMMUTABLE
        )
        return Notification.Builder(this, CHANNEL_ID)
            .setContentTitle("HyperOS充电优化")
            .setContentText(text)
            .setSmallIcon(android.R.drawable.ic_menu_info_details)
            .setContentIntent(pending)
            .setOngoing(true)
            .build()
    }

    private fun updateNotification(status: ChargeStatus) {
        val modeLabel = status.mode.label
        val temp = String.format("%.1f", status.tempC)
        val power = String.format("%.1f", status.powerW)
        val text = "$modeLabel | ${status.soc}% | ${temp}°C | ${power}W"
        val nm = getSystemService(NOTIFICATION_SERVICE) as NotificationManager
        nm.notify(NOTIFICATION_ID, buildNotification(text))
    }
}

package com.pvpwhgame.hyperoscharge.data

import org.json.JSONObject

data class ChargeStatus(
    val charging: Boolean = false,
    val mode: ChargeMode = ChargeMode.BALANCE,
    val soc: Int = 0,
    val temp: Int = 0,
    val tempTier: Int = 0,
    val socTier: Int = 0,
    val finalTier: Int = 0,
    val state: Int = 0,
    val maxstate: Int = 16,
    val powerDw: Long = 0,
    val ts: Long = 0
) {
    val tempC: Float get() = temp / 10f
    val powerW: Float get() = powerDw / 10f
    val statePercent: Float get() = if (maxstate > 0) state.toFloat() / maxstate else 0f

    companion object {
        fun parse(json: String): ChargeStatus {
            val o = JSONObject(json)
            if (o.optString("error") == "no_battery_cdev") {
                return ChargeStatus()
            }
            return ChargeStatus(
                charging = o.optBoolean("charging", false),
                mode = ChargeMode.fromKey(o.optString("mode", "balance")),
                soc = o.optInt("soc", 0),
                temp = o.optInt("temp", 0),
                tempTier = o.optInt("temp_tier", 0),
                socTier = o.optInt("soc_tier", 0),
                finalTier = o.optInt("final_tier", 0),
                state = o.optInt("state", 0),
                maxstate = o.optInt("maxstate", 16),
                powerDw = o.optLong("power_dw", 0),
                ts = o.optLong("ts", 0)
            )
        }
    }
}

package com.pvpwhgame.hyperoscharge.data

data class HistoryPoint(
    val ts: Long,
    val charging: Int,
    val soc: Int,
    val temp: Int,
    val state: Int,
    val maxstate: Int,
    val mode: String,
    val powerDw: Long
) {
    val tempC: Float get() = temp / 10f
    val powerW: Float get() = powerDw / 10f
    val statePercent: Float get() = if (maxstate > 0) state.toFloat() / maxstate else 0f

    companion object {
        fun parseCsv(text: String): List<HistoryPoint> {
            return text.trim().split("\n")
                .filter { it.isNotBlank() }
                .mapNotNull { line ->
                    val parts = line.split(",")
                    if (parts.size >= 7) {
                        HistoryPoint(
                            ts = parts[0].toLongOrNull() ?: return@mapNotNull null,
                            charging = parts[1].toIntOrNull() ?: 0,
                            soc = parts[2].toIntOrNull() ?: 0,
                            temp = parts[3].toIntOrNull() ?: 0,
                            state = parts[4].toIntOrNull() ?: 0,
                            maxstate = parts[5].toIntOrNull() ?: 16,
                            mode = parts[6],
                            powerDw = parts.getOrNull(7)?.toLongOrNull() ?: 0
                        )
                    } else null
                }
        }
    }
}

package com.pvpwhgame.hyperoscharge.data

data class LearnData(
    val learnedState: Int = 0,
    val learnedPowerDw: Long = 0,
    val learnedDur: Int = 0,
    val sessionCount: Int = 0,
    val maxPowerDw: Long = 0
) {
    val hasData: Boolean get() = sessionCount > 0 || learnedState > 0

    val learnedPowerW: Float get() = learnedPowerDw / 10f
    val maxPowerW: Float get() = maxPowerDw / 10f

    val learnedDurFormatted: String
        get() {
            if (learnedDur <= 0) return "—"
            val m = learnedDur / 60
            val s = learnedDur % 60
            return if (m > 0) "${m}分${s.toString().padStart(2, '0')}秒" else "${s}秒"
        }

    val learnedStatePercent: Int
        get() = if (MAX_STATE > 0) learnedState * 100 / MAX_STATE else 0

    companion object {
        private const val MAX_STATE = 16

        fun parse(content: String): LearnData {
            val map = content.lines()
                .filter { it.contains('=') }
                .associate {
                    val (k, v) = it.split('=', limit = 2)
                    k.trim() to v.trim()
                }
            return LearnData(
                learnedState = map["LEARNED_STATE"]?.toIntOrNull() ?: 0,
                learnedPowerDw = map["LEARNED_POWER_DW"]?.toLongOrNull() ?: 0,
                learnedDur = map["LEARNED_DUR"]?.toIntOrNull() ?: 0,
                sessionCount = map["SESSION_COUNT"]?.toIntOrNull() ?: 0,
                maxPowerDw = map["LEARNED_MAX_POWER_DW"]?.toLongOrNull() ?: 0
            )
        }
    }
}

