package com.pvpwhgame.hyperoscharge.data

import com.topjohnwu.superuser.Shell
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext

object ShellExecutor {

    suspend fun readFile(path: String): String? = withContext(Dispatchers.IO) {
        try {
            val result = Shell.cmd("cat '$path'").exec()
            if (result.isSuccess) result.out.joinToString("\n") else null
        } catch (_: Exception) { null }
    }

    suspend fun writeFile(path: String, content: String): Boolean = withContext(Dispatchers.IO) {
        try {
            Shell.cmd("echo '$content' > '$path'").exec().isSuccess
        } catch (_: Exception) { false }
    }

    suspend fun exec(cmd: String): Pair<Int, String> = withContext(Dispatchers.IO) {
        try {
            val result = Shell.cmd(cmd).exec()
            val out = result.out.joinToString("\n")
            Pair(result.code, out)
        } catch (e: Exception) {
            Pair(-1, e.message ?: "error")
        }
    }
}

package com.pvpwhgame.hyperoscharge

import android.content.Intent
import android.os.Build
import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.rememberScrollState
import androidx.compose.foundation.verticalScroll
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import com.pvpwhgame.hyperoscharge.data.ChargeMode
import com.pvpwhgame.hyperoscharge.data.ModuleConfig
import com.pvpwhgame.hyperoscharge.data.ShellExecutor
import com.pvpwhgame.hyperoscharge.service.ChargeMonitorService
import com.pvpwhgame.hyperoscharge.ui.*
import com.pvpwhgame.hyperoscharge.ui.theme.ChargeOptimizerTheme
import kotlinx.coroutines.launch

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {
            window.setDecorFitsSystemWindows(false)
        }

        setContent {
            ChargeOptimizerTheme {
                MainScreen()
            }
        }
    }
}

@Composable
fun MainScreen() {
    val context = LocalContext.current
    val status by ChargeMonitorService.statusFlow.collectAsState()
    val history by ChargeMonitorService.historyFlow.collectAsState()
    val learnDataMap by ChargeMonitorService.learnDataFlow.collectAsState()
    val modeDescs by ChargeMonitorService.modeDescsFlow.collectAsState()
    val scope = rememberCoroutineScope()

    var fastAccepted by remember { mutableStateOf(false) }
    var showFastDialog by remember { mutableStateOf(false) }
    var pendingMode by remember { mutableStateOf<ChargeMode?>(null) }

    // 启动时检查快充确认状态并启动服务
    LaunchedEffect(Unit) {
        val (code, out) = ShellExecutor.exec("cat ${ModuleConfig.FAST_ACCEPT_FILE}")
        fastAccepted = code == 0 && out.trim() == "1"

        val intent = Intent(context, ChargeMonitorService::class.java)
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            context.startForegroundService(intent)
        } else {
            context.startService(intent)
        }
    }

    fun selectMode(mode: ChargeMode) {
        if ((mode == ChargeMode.FAST || mode == ChargeMode.FAST_COOLER) && !fastAccepted) {
            pendingMode = mode
            showFastDialog = true
        } else {
            scope.launch {
                ShellExecutor.writeFile(ModuleConfig.MODE_FILE, mode.key)
            }
        }
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .verticalScroll(rememberScrollState())
            .padding(horizontal = 16.dp)
            .padding(top = 16.dp)
            .windowInsetsPadding(WindowInsets.statusBars)
    ) {
        // 实时状态卡片
        StatusCard(status)
        Spacer(Modifier.height(14.dp))

        // 本次充电统计
        ChargeStatsCard(history)
        Spacer(Modifier.height(14.dp))

        // 温度/限流曲线
        TempThrottleChart(history)
        Spacer(Modifier.height(14.dp))

        // 功率曲线
        PowerChart(history)
        Spacer(Modifier.height(14.dp))

        // 模式选择器（含当前模式学习数据，模式描述从 HTML 自动读取）
        ModeSelector(
            currentMode = status.mode,
            modeDescs = modeDescs,
            learnDataMap = learnDataMap,
            onModeSelected = { selectMode(it) }
        )
        Spacer(Modifier.height(14.dp))
    }

    if (showFastDialog) {
        FastModeDialog(
            onConfirm = {
                showFastDialog = false
                fastAccepted = true
                scope.launch {
                    ShellExecutor.writeFile(ModuleConfig.FAST_ACCEPT_FILE, "1")
                    pendingMode?.let {
                        ShellExecutor.writeFile(ModuleConfig.MODE_FILE, it.key)
                    }
                }
                pendingMode = null
            },
            onDismiss = {
                showFastDialog = false
                pendingMode = null
            }
        )
    }
}

@Composable
private fun ChargeStatsCard(history: List<com.pvpwhgame.hyperoscharge.data.HistoryPoint>) {
    val chPoints = remember(history) { history.filter { it.charging == 1 } }

    androidx.compose.material3.Card(
        modifier = Modifier.fillMaxWidth(),
        colors = androidx.compose.material3.CardDefaults.cardColors(
            containerColor = androidx.compose.ui.graphics.Color(0xFF1A1A20)
        ),
        shape = androidx.compose.foundation.shape.RoundedCornerShape(14.dp)
    ) {
        Column(modifier = Modifier.padding(16.dp)) {
            androidx.compose.material3.Text(
                "本次充电统计",
                fontSize = 14.sp,
                color = androidx.compose.ui.graphics.Color(0xFFAAAAAA)
            )
            Spacer(Modifier.height(8.dp))
            if (chPoints.size < 2) {
                androidx.compose.material3.Text(
                    "暂无本次充电数据",
                    fontSize = 13.sp,
                    color = androidx.compose.ui.graphics.Color(0xFFCCCCCC)
                )
            } else {
                val first = chPoints.first()
                val last = chPoints.last()
                val durSec = (last.ts - first.ts).coerceAtLeast(0)
                val h = durSec / 3600; val m = (durSec % 3600) / 60
                val durStr = if (h > 0) "${h}h${m.toString().padStart(2, '0')}m" else "${m}m"
                val socDelta = last.soc - first.soc
                val socStr = "${if (socDelta >= 0) "+" else ""}$socDelta%（${first.soc}%→${last.soc}%）"

                var wh = 0.0
                for (i in 1 until chPoints.size) {
                    val dt = chPoints[i].ts - chPoints[i - 1].ts
                    if (dt <= 0 || dt > 30) continue
                    val avgW = (chPoints[i].powerW + chPoints[i - 1].powerW) / 2.0
                    wh += avgW * dt / 3600.0
                }

                androidx.compose.material3.Text(
                    "时长 $durStr · $socStr · 约${String.format("%.1f", wh)}Wh",
                    fontSize = 13.sp,
                    color = androidx.compose.ui.graphics.Color(0xFFCCCCCC),
                    lineHeight = 20.sp
                )
            }
        }
    }
}

