package com.pvpwhgame.hyperoscharge.ui

import com.pvpwhgame.hyperoscharge.data.ChargeMode
import com.pvpwhgame.hyperoscharge.data.ModuleConfig
import com.pvpwhgame.hyperoscharge.data.ShellExecutor

/**
 * 从模块 HTML 中解析模式描述，实现 App 与 WebUI 自动同步
 * HTML 中模式按钮格式：
 *   <button class="mode-btn" data-mode="balance" onclick="setMode('balance')">
 *     均衡 <small>目标46°C自学习+电量保护</small>
 *   </button>
 */
object ModuleHtmlParser {

    // 缓存解析结果，避免每次都读文件
    private var cachedDescs: Map<String, String>? = null
    private var lastHtmlContent: String? = null

    /**
     * 从模块 HTML 中读取模式描述，解析失败时返回 ChargeMode 的硬编码 desc 作为 fallback
     */
    suspend fun getModeDescriptions(): Map<String, String> {
        try {
            val html = ShellExecutor.readFile(ModuleConfig.INDEX_HTML)
                ?: return fallbackDescs()

            // 只有 HTML 内容变化时才重新解析
            if (html != lastHtmlContent) {
                lastHtmlContent = html
                cachedDescs = parseModeDescriptions(html)
            }
            return cachedDescs ?: fallbackDescs()
        } catch (_: Exception) {
            return fallbackDescs()
        }
    }

    /**
     * 从 HTML 中提取模式按钮的 label 和 desc
     */
    private fun parseModeDescriptions(html: String): Map<String, String> {
        val descs = mutableMapOf<String, String>()

        // 匹配模式按钮块：<button class="mode-btn" data-mode="xxx" onclick="...">
        //   Label <small>Description</small>
        // </button>
        val buttonRegex = Regex(
            """<button\s+class="mode-btn"\s+data-mode="(\w+)".*?>\s*(.+?)\s*</button>""",
            setOf(RegexOption.DOT_MATCHES_ALL)
        )

        for (match in buttonRegex.findAll(html)) {
            val mode = match.groupValues[1]
            val content = match.groupValues[2].trim()

            // 提取 label（<small> 之前的文字）和 desc（<small> 中的文字）
            val smallRegex = Regex("""(.+?)\s*<small>(.+?)</small>""", RegexOption.DOT_MATCHES_ALL)
            val smallMatch = smallRegex.find(content)
            if (smallMatch != null) {
                val label = smallMatch.groupValues[1].trim()
                val desc = smallMatch.groupValues[2].trim()
                descs[mode] = desc
            }
        }

        return descs.ifEmpty { fallbackDescs() }
    }

    /**
     * fallback：使用 ChargeMode 中的硬编码描述
     */
    private fun fallbackDescs(): Map<String, String> {
        return ChargeMode.entries.associate { it.key to it.desc }
    }
}

