package com.pvpwhgame.hyperoscharge.ui

import android.annotation.SuppressLint
import android.webkit.JavascriptInterface
import android.webkit.WebView
import android.webkit.WebViewClient
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.viewinterop.AndroidView
import com.pvpwhgame.hyperoscharge.data.ModuleConfig
import com.pvpwhgame.hyperoscharge.data.ShellExecutor
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch

@SuppressLint("SetJavaScriptEnabled")
@Composable
fun ModuleWebView(
    modifier: Modifier = Modifier,
    onModeChanged: ((String) -> Unit)? = null
) {
    AndroidView(
        modifier = modifier,
        factory = { context ->
            WebView(context).apply {
                settings.javaScriptEnabled = true
                settings.domStorageEnabled = true
                settings.allowFileAccess = true
                settings.allowContentAccess = true
                settings.defaultTextEncodingName = "UTF-8"

                // 注入 ksu 替代对象，使 HTML 的 ksu.exec 调用路由到 AndroidBridge
                val injectJs = """
                    (function() {
                        if (typeof window.ksu === 'undefined') {
                            window.ksu = {};
                        }
                        window.ksu.exec = function(cmd, options, cb) {
                            var cbId = '';
                            if (cb) {
                                cbId = '__cb_' + Date.now() + '_' + Math.random();
                                window[cbId] = cb;
                            }
                            AndroidBridge.exec(cmd, options || '{}', cbId);
                        };
                    })();
                """.trimIndent()

                webViewClient = object : WebViewClient() {
                    override fun onPageFinished(view: WebView?, url: String?) {
                        super.onPageFinished(view, url)
                        view?.evaluateJavascript(injectJs, null)
                    }
                }

                addJavascriptInterface(
                    ModuleBridge(this, onModeChanged),
                    "AndroidBridge"
                )

                loadUrl("file://${ModuleConfig.INDEX_HTML}")
            }
        }
    )
}

/**
 * JavaScript Bridge：替代 ksu.exec，通过 root shell 执行命令
 * 执行完成后回调 HTML 中的 callback 函数
 */
private class ModuleBridge(
    private val webView: WebView,
    private val onModeChanged: ((String) -> Unit)?
) {
    private val scope = CoroutineScope(Dispatchers.IO)

    @JavascriptInterface
    fun exec(cmd: String, options: String, callbackId: String) {
        scope.launch {
            try {
                val result = ShellExecutor.exec(cmd)
                val code = result.first
                val stdout = result.second.replace("\\", "\\\\").replace("'", "\\'").replace("\n", "\\n")

                // 如果是模式切换命令，通知 native 层
                if (cmd.contains("charge_mode")) {
                    val modeKey = cmd.substringAfter("echo ").substringBefore(" >").trim()
                    if (modeKey.isNotBlank()) {
                        onModeChanged?.invoke(modeKey)
                    }
                }

                // 回调 HTML 中的 callback 函数
                if (callbackId.isNotBlank()) {
                    val js = "javascript:try{window['$callbackId']($code,'$stdout')}catch(e){};delete window['$callbackId']"
                    webView.post { webView.evaluateJavascript(js, null) }
                }
            } catch (e: Exception) {
                if (callbackId.isNotBlank()) {
                    val js = "javascript:try{window['$callbackId'](-1,'${e.message?.replace("'", "\\'") ?: "error"}')}catch(e){};delete window['$callbackId']"
                    webView.post { webView.evaluateJavascript(js, null) }
                }
            }
        }
    }
}

