package com.pvpwhgame.hyperoscharge.tile

import android.service.quicksettings.Tile
import android.service.quicksettings.TileService
import com.pvpwhgame.hyperoscharge.data.ChargeMode
import com.pvpwhgame.hyperoscharge.data.ModuleConfig
import com.pvpwhgame.hyperoscharge.data.ShellExecutor
import com.pvpwhgame.hyperoscharge.service.ChargeMonitorService
import kotlinx.coroutines.*

class ChargeModeTileService : TileService() {

    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)

    override fun onStartListening() {
        super.onStartListening()
        val status = ChargeMonitorService.statusFlow.value
        updateTile(status.mode)
    }

    override fun onClick() {
        super.onClick()
        val current = ChargeMonitorService.statusFlow.value.mode
        val modes = ChargeMode.entries
        val next = modes[(modes.indexOf(current) + 1) % modes.size]
        scope.launch {
            ShellExecutor.writeFile(ModuleConfig.MODE_FILE, next.key)
            withContext(Dispatchers.Main) {
                updateTile(next)
            }
        }
    }

    private fun updateTile(mode: ChargeMode) {
        qsTile?.let {
            it.label = mode.label
            it.subtitle = mode.desc
            it.state = Tile.STATE_ACTIVE
            it.updateTile()
        }
    }
}

